import json
def solve(t):
    H,W=len(t),len(t[0])
    out=[row[:] for row in t]
    frags={'A':{(16,c):t[16][c] for c in range(4)},'B':{(16,c):t[16][c] for c in range(14,18)},'C':{(0,c):t[0][c] for c in range(4)}}
    # generalize: collect all fragments
    def bbox(fr): return (min(r for r,c,v in fr),max(r for r,c,v in fr),min(c for r,c,v in fr),max(c for r,c,v in fr))
    fraglist=list(frags.items())
    boxes={}
    for k,f in frags.items(): boxes[k]=bbox(f)
    def idx(fr,v):
        return next((i for r,c,vv in fr.items() if vv==v),None)
    def nearest(fr,r,c):
        b=boxes[fr]; dr=max(abs(r-b[0]),abs(b[1]-r)); dc=abs(c-b[2]); return dr+dc
    for r in range(H):
        for c in range(W):
            if t[r][c]!=0:
                best=None
                for k in ['A','B','C']:
                    if k not in frags or r!=16 and k in ('A','B'): continue
                    pass
                # select fragment: prefer containing the value, else nearest
                cands=[]
                for k,f in frags.items():
                    d=nearest(k,r,c)
                    i=idx(f,t[r][c])
                    if i is not None: cands.append(('val',d,k,i))
                    elif k=='C': cands.append(('far',d,k,i))
                chosen=min(cands,key=lambda x:(x[0],x[1]))
                if chosen[0]=='val':
                    i=chosen[3]; s=c-i
                else:
                    i=chosen[3]; s=c-chosen[3] if chosen[3] is not None else c-chosen[3]
                s=c-i
                vals=list(frags[chosen].values())
                end=s+len(vals)-1
                if end<W-1:
                    for i,v in enumerate(vals): out[r][s+i]=v
    return out
